css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .16); border-radius: calc(var(--loader-size) * .08); background: color-mix(in srgb, var(--accent) 20%, transparent); position: relative; overflow: hidden; }
.loader span { position: absolute; top: 0; height: 100%; width: 40%; border-radius: inherit; background: linear-gradient(90deg, var(--accent), var(--accent-2)); animation: slide calc(var(--loader-speed) * 1.6) cubic-bezier(.65, .05, .35, 1) infinite; }
@keyframes slide { 0% { left: -45%; } 100% { left: 105%; } }
